static sensors_snapshot_t test_readings;
static jmp_buf loop_escape;
static unsigned telemetry_calls;
static unsigned ride_update_calls;
static unsigned led_calls;
static bool led_values[4];
static unsigned page_calls;
static unsigned pages_at_splash_start;
static unsigned uart_handle_calls;

static uint32_t now_callback(int cmock_num_calls)
{
    /* Initialize at zero, advance past stabilization, then remain in the splash. */
    if (cmock_num_calls <= 2)
    {
        return 0U;
    }
    if (cmock_num_calls <= 4)
    {
        return UINT32_MAX;
    }
    if (cmock_num_calls == 5)
    {
        pages_at_splash_start = page_calls;
        return 100U;
    }
    return 100U;
}

static bool sh1106_page_callback(sh1106_send_t send, uint8_t address,
                                 uint8_t page, const uint8_t *pixels,
                                 int cmock_num_calls)
{
    (void)send;
    (void)address;
    (void)page;
    (void)pixels;
    (void)cmock_num_calls;
    page_calls++;
    return true;
}

static ride_event_t ride_update_callback(ride_events_t *state, uint32_t now_ms,
                                         bool *led_on, int cmock_num_calls)
{
    (void)state;
    (void)now_ms;
    (void)cmock_num_calls;
    ride_update_calls++;
    *led_on = true;
    return RIDE_SPEEDING;
}

static void led_callback(bool on, int cmock_num_calls)
{
    (void)cmock_num_calls;
    if (led_calls < (sizeof led_values / sizeof led_values[0]))
    {
        led_values[led_calls] = on;
    }
    led_calls++;
}

static void telemetry_callback(uint32_t now_ms,
                               const sensors_snapshot_t *readings,
                               ride_event_t event, int cmock_num_calls)
{
    (void)now_ms;
    (void)readings;
    (void)event;
    (void)cmock_num_calls;
    telemetry_calls++;
    if (telemetry_calls >= 2U)
    {
        longjmp(loop_escape, 1);
    }
}

/* This accessor is provided by the test because its source is not linked. */
UART_HandleTypeDef *firmgen_uart_handle(void)
{
    uart_handle_calls++;
    return NULL;
}

void setUp(void)
{
    memset(&test_readings, 0, sizeof test_readings);
    telemetry_calls = 0U;
    ride_update_calls = 0U;
    led_calls = 0U;
    memset(led_values, 0, sizeof led_values);
    page_calls = 0U;
    pages_at_splash_start = 0U;
    uart_handle_calls = 0U;

    platform_io_init_IgnoreAndReturn(true);
    platform_io_now_ms_StubWithCallback(now_callback);
    platform_io_log_Ignore();
    platform_io_poll_Ignore();
    platform_io_led_StubWithCallback(led_callback);

    sensors_init_Ignore();
    sensors_process_Ignore();
    sensors_snapshot_IgnoreAndReturn(&test_readings);

    ride_events_init_Ignore();
    ride_events_sample_Ignore();
    ride_events_update_StubWithCallback(ride_update_callback);
    ride_events_message_IgnoreAndReturn("ALERT");

    telemetry_process_StubWithCallback(telemetry_callback);
    firmgen_telemetry_start_Ignore();
    firmgen_telemetry_poll_Ignore();

    sh1106_init_IgnoreAndReturn(true);
    sh1106_page_StubWithCallback(sh1106_page_callback);
    sh1106_enable_IgnoreAndReturn(true);
}

void tearDown(void)
{
}

void test_FR_004_01(void)
{
    if (setjmp(loop_escape) == 0)
    {
        app_start();
    }

    /* The second loop pass is still inside the logo splash. */
    TEST_ASSERT_TRUE(display_is_splash());
    TEST_ASSERT_EQUAL_INT(0, (int)ride_update_calls);

    /* The splash transfer may write the logo, but must not start dashboard pages. */
    TEST_ASSERT_EQUAL_INT((int)pages_at_splash_start, (int)page_calls);

    /* Both loop passes command the LED off; neither produces an ON/blink command. */
    TEST_ASSERT_EQUAL_INT(2, (int)led_calls);
    TEST_ASSERT_FALSE(led_values[0]);
    TEST_ASSERT_FALSE(led_values[1]);
}
